#include <functional>
#include <string>
#include <vector>

std::vector<std::vector<std::string>> partition(const std::string& s) {
    int n = s.size();

    // isPal[i][j]: does s[i..j] read the same both ways?
    std::vector<std::vector<bool>> isPal(n, std::vector<bool>(n, false));
    for (int i = 0; i < n; i++) isPal[i][i] = true;
    for (int len = 2; len <= n; len++) {
        for (int i = 0; i + len - 1 < n; i++) {
            int j = i + len - 1;
            isPal[i][j] = s[i] == s[j] && (len == 2 || isPal[i + 1][j - 1]);
        }
    }

    std::vector<std::vector<std::string>> out;
    std::vector<std::string> parts;

    std::function<void(int)> backtrack = [&](int start) {
        if (start == n) {
            out.push_back(parts);
            return;
        }

        for (int end = start; end < n; end++) {
            if (!isPal[start][end]) continue;   // prune: no cut here can work

            parts.push_back(s.substr(start, end - start + 1));  // choose
            backtrack(end + 1);                                 // explore
            parts.pop_back();                                   // un-choose
        }
    };

    backtrack(0);
    return out;
}
